function doMidnightUpdate() {
  if (TodayPane.showsToday) {
    // Select today.
    TodayPane.setDay(cal.dtz.now());
  } else {
    // Just update the day displayed as today.
    const todayMinimonth = document.getElementById("today-minimonth");
    todayMinimonth.showMonth(todayMinimonth.value);
    const minidayMinimonth = document.getElementById("miniday-dropdown-minimonth");
    minidayMinimonth.showMonth(minidayMinimonth.value);
  }

  for (const view of getViewBox().children) {
    // Mark each view as invalid to ensure it gets redrawn next time it is shown.
    view.mToggleStatus = -1;
  }

  const minimonth = getMinimonth();
  if (minimonth.showsToday) {
    // Select today.
    minimonth.value = new Date();
  } else {
    // Just update the day displayed as today.
    minimonth.showMonth(minimonth.mEditorDate);
    const view = currentView();
    if (view.isInitialized) {
      view.goToDay();
    }
  }

// Note that aMainDate and this.mEditorDate refer to the first day
// of the corresponding month.
const sameMonth = this._sameDay(aMainDate, this.mEditorDate);
const sameDate = this._sameDay(aDate, this.mValue);
if (!sameMonth && !sameDate) {
  // Change month and select day.
  this.mValue = aDate;
  const today = new Date();
  this.mShowsToday =
    this.mValue.getFullYear() == today.getFullYear() &&
    this.mValue.getMonth() == today.getMonth() &&
    this.mValue.getDate() == today.getDate();
  this.showMonth(aMainDate);
} else if (!sameMonth) {
  // Change month only.
  this.showMonth(aMainDate);
} else if (!sameDate) {
  // Select day only.
  const day = this.getBoxForDate(aDate);
  if (this.mSelected) {
    this.mSelected.removeAttribute("selected");
  }
  this.mSelected = day;
  day.toggleAttribute("selected", true);
  this.mValue = aDate;
  const today = new Date();
  this.mShowsToday =
    this.mValue.getFullYear() == today.getFullYear() &&
    this.mValue.getMonth() == today.getMonth() &&
    this.mValue.getDate() == today.getDate();
  this.setFocusedDate(aDate);
}
